Here is the fibonacci generator using `next(x)` to restart the sequence:

```js
function* fibonacci() {
 let current = 0;
 let next = 1;
 while (true) {
 const reset = yield current;
 [current, next] = [next, next + current];
 if (reset) {
 current = 0;
 next = 1;
 }
 }
}

const sequence = fibonacci();
